/**
 * Fill a new store with demo content so its look can be judged before the
 * client's real products exist. Content lives in scripts/demo/content.mjs.
 *
 *   node scripts/seed-demo.mjs               # generate missing images, replace all demo docs
 *   node scripts/seed-demo.mjs --images-only # just generate + upload images
 *   node scripts/seed-demo.mjs --remove      # delete every demo doc (before launch)
 *
 * Images: generated by Pollinations (free, no key), watermark cropped off,
 * compressed with sharp, uploaded to Cloudinary with the unsigned preset.
 * URLs are cached in scripts/demo/images.json, so re-runs reuse them; delete an
 * entry (or change its prompt) to regenerate that image.
 *
 * Every document written here carries `demo: true` and is an ordinary record,
 * so the admin panel can edit or delete it one by one. Categories are the one
 * exception: they are the store's real starting categories, so they're only
 * created when missing and are never removed.
 *
 * Needs in .env: FIREBASE_ADMIN_SDK_BASE64, VITE_FIREBASE_PROJECT_ID,
 * VITE_CLOUDINARY_CLOUD_NAME, VITE_CLOUDINARY_UPLOAD_PRESET.
 */
import 'dotenv/config';
import admin from 'firebase-admin';
import sharp from 'sharp';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import {
  STYLE, CATEGORIES, PRODUCTS, HERO_BANNERS, SHOWCASES, COLLECTIONS, COLLECTION_BANNER, TESTIMONIALS,
} from './demo/content.mjs';

const REMOVE = process.argv.includes('--remove');
const IMAGES_ONLY = process.argv.includes('--images-only');
const CACHE_FILE = new URL('./demo/images.json', import.meta.url);

/** Collections that hold demo docs, cleared by --remove and before each seed. */
const DEMO_COLLECTIONS = ['products', 'banners', 'showcases', 'homeCollections', 'homeBanners', 'testimonials'];

const {
  FIREBASE_ADMIN_SDK_BASE64, VITE_FIREBASE_PROJECT_ID, VITE_CLOUDINARY_CLOUD_NAME, VITE_CLOUDINARY_UPLOAD_PRESET,
} = process.env;
if (!FIREBASE_ADMIN_SDK_BASE64) {
  console.error('FIREBASE_ADMIN_SDK_BASE64 missing from .env');
  process.exit(1);
}

admin.initializeApp({
  credential: admin.credential.cert(JSON.parse(Buffer.from(FIREBASE_ADMIN_SDK_BASE64, 'base64').toString('utf8'))),
});
const db = admin.firestore();
const now = admin.firestore.FieldValue.serverTimestamp;

const slugify = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ── Images ──────────────────────────────────────────────────────────────────

/** Pollinations stamps its logo in the bottom-right corner; this many px are cut off the bottom. */
const WATERMARK_PX = 48;

async function generate(prompt, width, height, seed) {
  const url =
    `https://image.pollinations.ai/prompt/${encodeURIComponent(`${prompt}, ${STYLE}`)}` +
    `?width=${width}&height=${height}&nologo=true&seed=${seed}`;
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      const resp = await fetch(url, { signal: AbortSignal.timeout(180_000) });
      if (resp.ok && (resp.headers.get('content-type') || '').startsWith('image/')) {
        return Buffer.from(await resp.arrayBuffer());
      }
      console.warn(`  generator HTTP ${resp.status}, retrying (${attempt}/5)`);
    } catch (err) {
      console.warn(`  generator error: ${err.message}, retrying (${attempt}/5)`);
    }
    await sleep(15_000 * attempt);
  }
  throw new Error(`image generation failed: ${prompt.slice(0, 60)}`);
}

/** Crop the watermark, fit to the target size, and compress under maxBytes. */
async function finish(buffer, width, height, maxBytes) {
  const meta = await sharp(buffer).metadata();
  const cropped = await sharp(buffer)
    .extract({ left: 0, top: 0, width: meta.width, height: meta.height - WATERMARK_PX })
    .toBuffer();
  for (let quality = 84; quality >= 50; quality -= 6) {
    const out = await sharp(cropped)
      .resize(width, height, { fit: 'cover', position: 'attention' })
      .jpeg({ quality, mozjpeg: true })
      .toBuffer();
    if (out.length <= maxBytes) return out;
  }
  throw new Error('could not compress image under the size limit');
}

async function uploadToCloudinary(buffer, name) {
  if (!VITE_CLOUDINARY_CLOUD_NAME || !VITE_CLOUDINARY_UPLOAD_PRESET) {
    throw new Error('VITE_CLOUDINARY_CLOUD_NAME / VITE_CLOUDINARY_UPLOAD_PRESET missing from .env');
  }
  const form = new FormData();
  form.append('file', new Blob([buffer], { type: 'image/jpeg' }), `${name}.jpg`);
  form.append('upload_preset', VITE_CLOUDINARY_UPLOAD_PRESET);
  form.append('folder', `${VITE_FIREBASE_PROJECT_ID}/demo`);
  const resp = await fetch(`https://api.cloudinary.com/v1_1/${VITE_CLOUDINARY_CLOUD_NAME}/image/upload`, {
    method: 'POST',
    body: form,
  });
  const json = await resp.json();
  if (!resp.ok || !json.secure_url) throw new Error(`Cloudinary: ${json.error?.message || resp.status}`);
  return json.secure_url;
}

const cache = existsSync(CACHE_FILE) ? JSON.parse(await readFile(CACHE_FILE, 'utf8')) : {};

/**
 * URL for one image, generating it only when its key + prompt + size aren't cached.
 * Generation asks for a size the free tier accepts; `out` is the delivered size.
 */
async function image(key, prompt, gen, out, maxBytes) {
  const hash = createHash('sha1').update(`${prompt}|${STYLE}|${out.join('x')}`).digest('hex').slice(0, 10);
  if (cache[key]?.hash === hash) return cache[key].url;

  const seed = parseInt(hash.slice(0, 6), 16) % 100000;
  console.log(`  generating ${key} ...`);
  const raw = await generate(prompt, gen[0], gen[1] + WATERMARK_PX, seed);
  const jpeg = await finish(raw, out[0], out[1], maxBytes);
  const url = await uploadToCloudinary(jpeg, key.replace(/[^a-z0-9-]+/gi, '-'));
  cache[key] = { hash, url };
  await writeFile(CACHE_FILE, JSON.stringify(cache, null, 2) + '\n');
  return url;
}

const KB = 1024;
const SIZES = {
  product: { gen: [768, 720], out: [800, 800], max: 480 * KB },
  heroDesktop: { gen: [1024, 576], out: [1600, 900], max: 1000 * KB },
  heroMobile: { gen: [640, 800], out: [960, 1200], max: 1000 * KB },
  showcase: { gen: [960, 640], out: [1200, 800], max: 480 * KB },
  collection: { gen: [600, 800], out: [900, 1200], max: 480 * KB },
  wide: { gen: [1024, 410], out: [1600, 640], max: 1000 * KB },
};
const img = (key, prompt, size) => image(key, prompt, SIZES[size].gen, SIZES[size].out, SIZES[size].max);

async function buildImages() {
  const urls = { products: {}, hero: [], showcases: [], collections: [], wide: '' };
  for (const p of PRODUCTS) urls.products[p.name] = await img(`product-${slugify(p.name)}`, p.prompt, 'product');
  for (const [i, b] of HERO_BANNERS.entries()) {
    urls.hero.push({
      desktop: await img(`hero-${i + 1}-desktop`, b.prompt, 'heroDesktop'),
      mobile: await img(`hero-${i + 1}-mobile`, `${b.prompt}, vertical composition`, 'heroMobile'),
    });
  }
  for (const [i, s] of SHOWCASES.entries()) urls.showcases.push(await img(`showcase-${i + 1}`, s.prompt, 'showcase'));
  for (const [i, c] of COLLECTIONS.entries()) urls.collections.push(await img(`collection-${i + 1}`, c.prompt, 'collection'));
  urls.wide = await img('collection-wide', COLLECTION_BANNER.prompt, 'wide');
  return urls;
}

// ── Firestore ───────────────────────────────────────────────────────────────

async function removeDemoDocs() {
  let total = 0;
  for (const name of DEMO_COLLECTIONS) {
    const snap = await db.collection(name).where('demo', '==', true).get();
    for (let i = 0; i < snap.docs.length; i += 400) {
      const batch = db.batch();
      snap.docs.slice(i, i + 400).forEach((d) => batch.delete(d.ref));
      await batch.commit();
    }
    if (snap.size) console.log(`  removed ${snap.size} from ${name}`);
    total += snap.size;
  }
  return total;
}

async function ensureCategories() {
  for (const c of CATEGORIES) {
    const ref = db.collection('categories').doc(c.slug);
    if ((await ref.get()).exists) continue;
    await ref.set({
      name: c.name,
      slug: c.slug,
      subcategories: c.subs.map((name) => ({ name, slug: slugify(name), children: [] })),
      createdAt: now(),
      updatedAt: now(),
    });
    console.log(`  created category ${c.name}`);
  }
}

const FLAG_LETTERS = { T: 'isTopDeal', B: 'isBestSeller', F: 'isFeatured', N: 'isNewArrival', R: 'isTrendProduct' };

async function writeDemoDocs(urls) {
  const batch = db.batch();
  const add = (collection, data) => batch.set(db.collection(collection).doc(), { ...data, demo: true });
  const base = Date.now();

  PRODUCTS.forEach((p, i) => {
    const flags = { isActive: true, isFeatured: false, isNewArrival: false, isBestSeller: false, isTopDeal: false, isTrendProduct: false };
    for (const letter of p.flags) flags[FLAG_LETTERS[letter]] = true;
    const photo = urls.products[p.name];
    // Staggered so "newest first" keeps the order written here.
    const createdAt = admin.firestore.Timestamp.fromMillis(base - i * 60_000);
    add('products', {
      name: p.name,
      slug: slugify(p.name),
      barcode: null,
      category: p.category,
      subcategory: p.subcategory,
      subSubcategory: null,
      description: p.description,
      price: p.price,
      originalPrice: p.originalPrice,
      discount: Math.round((1 - p.price / p.originalPrice) * 100),
      currency: 'INR',
      media: { images: [photo], videos: [], thumbnail: photo },
      inventory: { stock: p.stock, sku: '', weight: p.weight, weightUnit: 'grams' },
      specifications: p.specs,
      flags,
      inactiveReason: null,
      delivery: null,
      silverPricing: { enabled: false },
      createdBy: 'seed-demo',
      createdAt,
      updatedAt: createdAt,
    });
  });

  HERO_BANNERS.forEach((b, i) =>
    add('banners', {
      imageUrl: urls.hero[i].desktop,
      mobileImageUrl: urls.hero[i].mobile,
      redirectLink: b.link,
      order: i,
      status: 'active',
      createdAt: now(),
      updatedAt: now(),
    }),
  );

  SHOWCASES.forEach((s, i) =>
    add('showcases', {
      title: s.title,
      subtitle: s.subtitle,
      description: s.description,
      cta: s.cta,
      imageUrl: urls.showcases[i],
      order: i,
      status: 'active',
      createdAt: now(),
      updatedAt: now(),
    }),
  );

  COLLECTIONS.forEach((c, i) =>
    add('homeCollections', {
      eyebrow: c.eyebrow,
      title: c.title,
      subtitle: c.subtitle,
      ctaLabel: 'Explore',
      ctaLink: c.link,
      imageUrl: urls.collections[i],
      active: true,
      order: i,
      createdAt: now(),
      updatedAt: now(),
    }),
  );

  const { prompt: _prompt, ...wide } = COLLECTION_BANNER;
  add('homeBanners', { ...wide, slot: 'collection-wide', imageUrl: urls.wide, active: true, order: 0, createdAt: now(), updatedAt: now() });

  TESTIMONIALS.forEach((t, i) =>
    add('testimonials', { ...t, avatarType: 'avatar', avatarUrl: '', order: i, status: 'active', createdAt: now(), updatedAt: now() }),
  );

  await batch.commit();
}

// ── Main ────────────────────────────────────────────────────────────────────

if (REMOVE) {
  const n = await removeDemoDocs();
  console.log(`Removed ${n} demo documents. (Cloudinary files stay: an unsigned preset can't delete.)`);
  process.exit(0);
}

console.log('Images:');
const urls = await buildImages();
if (IMAGES_ONLY) process.exit(0);

console.log('Firestore:');
await ensureCategories();
await removeDemoDocs();
await writeDemoDocs(urls);
console.log(
  `Wrote ${PRODUCTS.length} products, ${HERO_BANNERS.length} hero banners, ${SHOWCASES.length} showcases, ` +
    `${COLLECTIONS.length} collections, 1 wide banner, ${TESTIMONIALS.length} testimonials (all demo: true).`,
);
process.exit(0);
